import { useState } from 'react';
import './App.css';

const avatarOptions = [
  {
    id: 'sunset-stack',
    label: 'Sunset Stack',
    initials: 'SS',
    description: 'Bright favorites and easy rewatches.',
    className: 'avatar--sunset',
  },
  {
    id: 'arcade-tape',
    label: 'Arcade Tape',
    initials: 'AT',
    description: 'Big reactions, sharp opinions, loud taste.',
    className: 'avatar--arcade',
  },
  {
    id: 'indie-shelf',
    label: 'Indie Shelf',
    initials: 'IS',
    description: 'Cozy gems, hidden finds, patient curation.',
    className: 'avatar--indie',
  },
  {
    id: 'midnight-reel',
    label: 'Midnight Reel',
    initials: 'MR',
    description: 'Late-night binges and dramatic finales.',
    className: 'avatar--midnight',
  },
];

function App() {
  const [formData, setFormData] = useState({
    username: '',
    bio: '',
    avatarId: avatarOptions[0].id,
  });
  const [profile, setProfile] = useState(null);

  const activeAvatar =
    avatarOptions.find((option) => option.id === formData.avatarId) ||
    avatarOptions[0];
  const previewProfile = profile || {
    username: formData.username.trim() || 'your_name',
    bio:
      formData.bio.trim() ||
      'Add a short bio so the community can tell what you love to watch, read, and play.',
    avatar: activeAvatar,
  };

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const handleAvatarSelect = (avatarId) => {
    setFormData((current) => ({
      ...current,
      avatarId,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    const username = formData.username.trim();
    const bio = formData.bio.trim();

    if (!username || !bio) {
      return;
    }

    setProfile({
      username,
      bio,
      avatar: activeAvatar,
    });
  };

  return (
    <div className="app-shell">
      <main className="app-layout">
        <section className="panel intro-panel">
          <p className="eyebrow">Media journal beta</p>
          <h1>Build your basic account before the social features arrive.</h1>
          <p className="lede">
            Create a simple profile with a username, bio, and avatar. Media
            logging, reviews, and community tools are represented below with
            placeholder text until those features are fully built.
          </p>

          <div className="pill-row">
            <span className="pill">Basic sign up is live</span>
            <span className="pill pill--muted">Media history is placeholder</span>
            <span className="pill pill--muted">Community tools are placeholder</span>
          </div>

          <div className="profile-preview">
            <div
              className={`avatar-preview ${previewProfile.avatar.className}`}
              aria-hidden="true"
            >
              {previewProfile.avatar.initials}
            </div>

            <div className="profile-copy">
              <p className="profile-kicker">Live profile preview</p>
              <h2>@{previewProfile.username}</h2>
              <p>{previewProfile.bio}</p>
            </div>
          </div>
        </section>

        <section className="panel signup-panel">
          <div className="panel-header">
            <p className="eyebrow">Create account</p>
            <h2>Basic sign up</h2>
            <p>
              Start with the essentials now, then expand your account once
              saved media, reviews, and social interactions are connected.
            </p>
          </div>

          {profile ? (
            <p className="status-banner" role="status">
              Local account created. Media history and community features are
              placeholders for now.
            </p>
          ) : null}

          <form className="signup-form" onSubmit={handleSubmit}>
            <label className="field">
              <span>Username</span>
              <input
                name="username"
                type="text"
                placeholder="movie_maven"
                value={formData.username}
                onChange={handleChange}
                maxLength="24"
                required
              />
            </label>

            <label className="field">
              <span>Bio</span>
              <textarea
                name="bio"
                placeholder="Tell people what you love to watch, read, or play."
                value={formData.bio}
                onChange={handleChange}
                rows="4"
                maxLength="160"
                required
              />
            </label>

            <fieldset className="avatar-fieldset">
              <legend>Avatar</legend>

              <div className="avatar-grid">
                {avatarOptions.map((option) => {
                  const isSelected = option.id === formData.avatarId;

                  return (
                    <button
                      key={option.id}
                      type="button"
                      className={`avatar-option${
                        isSelected ? ' is-selected' : ''
                      }`}
                      onClick={() => handleAvatarSelect(option.id)}
                      aria-pressed={isSelected}
                    >
                      <span
                        className={`avatar-swatch ${option.className}`}
                        aria-hidden="true"
                      >
                        {option.initials}
                      </span>
                      <span className="avatar-option-title">{option.label}</span>
                      <span className="avatar-option-copy">
                        {option.description}
                      </span>
                    </button>
                  );
                })}
              </div>
            </fieldset>

            <button className="primary-button" type="submit">
              {profile ? 'Update local account' : 'Create local account'}
            </button>

            <p className="fine-print">
              Placeholder note: authentication, real media logs, follows,
              comments, and notifications are not built yet.
            </p>
          </form>
        </section>

        <section className="panel dashboard-panel panel--wide">
          <div className="panel-header">
            <p className="eyebrow">Profile hub</p>
            <h2>
              {profile
                ? `Welcome, @${profile.username}`
                : 'Your profile hub will unlock here'}
            </h2>
            <p>
              {profile
                ? 'Your basic account is ready. These cards show where media history and community features will plug in next.'
                : 'Create your account to personalize the placeholder areas for media logging and community interaction.'}
            </p>
          </div>

          <div className="dashboard-grid">
            <article className="feature-card">
              <span className="card-tag">Placeholder</span>
              <h3>Media history</h3>
              <p>
                {profile
                  ? `Soon you will log watched, played, and finished titles under @${profile.username}.`
                  : 'Soon you will track watched, played, and finished titles here.'}
              </p>
              <button className="ghost-button" type="button" disabled>
                Logging tools coming soon
              </button>
            </article>

            <article className="feature-card">
              <span className="card-tag">Placeholder</span>
              <h3>Community lounge</h3>
              <p>
                Community replies, follows, and direct recommendations are
                coming soon. For now, this panel simply reserves the space.
              </p>
              <button className="ghost-button" type="button" disabled>
                Social actions coming soon
              </button>
            </article>

            <article className="feature-card">
              <span className="card-tag">Placeholder</span>
              <h3>Profile activity</h3>
              <p>
                Future updates will show recent reviews, reactions, and media
                milestones. This is placeholder text until the feed exists.
              </p>
              <button className="ghost-button" type="button" disabled>
                Activity feed coming soon
              </button>
            </article>
          </div>
        </section>
      </main>
    </div>
  );
}

export default App;
